	require.NotEmpty(t, toolUseID, "tool_use_id is required to locate committed task checkpoint")

	path := testutil.CheckpointPath(checkpointID) + "/0/tasks/" + toolUseID + "/checkpoint.json"
	blob := "entire/checkpoints/v1:" + path
